const input = $input.first().json;
const body = input.body || {};

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateEmail(email) {
  return typeof email === 'string' && emailRegex.test(email.trim());
}

const to = body.to ? String(body.to).trim() : '';
if (!to) {
  return [{ json: { valid: false, success: false, error: "VALIDATION_ERROR", message: "Missing required field: 'to'" } }];
}
if (!validateEmail(to)) {
  return [{ json: { valid: false, success: false, error: "VALIDATION_ERROR", message: "Invalid email format for 'to'" } }];
}

let replyTo = body.replyTo ? String(body.replyTo).trim() : 'support@acya.site';
if (body.replyTo && !validateEmail(replyTo)) {
  return [{ json: { valid: false, success: false, error: "VALIDATION_ERROR", message: "Invalid email format for 'replyTo'" } }];
}

let template = body.template ? String(body.template).trim().toLowerCase() : '';
if (!template && body.subject && body.html) {
  template = 'raw';
}

if (!template) {
  return [{ json: { valid: false, success: false, error: "VALIDATION_ERROR", message: "Missing required field: 'template'" } }];
}

const TEMPLATES = {
  welcome: (vars) => {
    const companyName = vars && vars.companyName ? String(vars.companyName).trim() : '';
    const contactName = vars && vars.contactName ? String(vars.contactName).trim() : (companyName || 'Cher Client');
    const tenantUrl = vars && vars.tenantUrl ? String(vars.tenantUrl).trim() : 'https://acya.site';

    if (!companyName) {
      return { error: "Missing required variable 'companyName' for template 'welcome'" };
    }

    const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Bienvenue chez ACYA</title>
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f4f6f8; margin: 0; padding: 20px; color: #1e293b;">
  <div style="max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
    <div style="background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%); padding: 32px 24px; text-align: center;">
      <h1 style="color: #ffffff; margin: 0; font-size: 26px; font-weight: 700; letter-spacing: -0.5px;">ACYA SaaS</h1>
      <p style="color: #93c5fd; margin: 6px 0 0 0; font-size: 14px;">Plateforme Multi-Tenant Entreprise</p>
    </div>
    <div style="padding: 32px 24px;">
      <h2 style="color: #0f172a; font-size: 20px; font-weight: 600; margin-top: 0;">Bienvenue ${contactName} !</h2>
      <p style="font-size: 15px; line-height: 1.6; color: #334155;">
        Nous avons le plaisir de vous confirmer que votre entreprise <strong>${companyName}</strong> a été enregistrée avec succès sur la plateforme ACYA.
      </p>
      <div style="background-color: #f8fafc; border-left: 4px solid #3b82f6; padding: 16px; margin: 24px 0; border-radius: 0 8px 8px 0;">
        <p style="margin: 0 0 8px 0; font-size: 14px; font-weight: 600; color: #475569;">Votre espace de travail dédié :</p>
        <a href="${tenantUrl}" style="color: #2563eb; font-weight: 700; font-size: 16px; text-decoration: none;">${tenantUrl}</a>
      </div>
      <p style="font-size: 14px; line-height: 1.6; color: #64748b;">
        Si vous avez la moindre question, notre équipe de support se tient à votre disposition à l'adresse <a href="mailto:support@acya.site" style="color: #2563eb;">support@acya.site</a>.
      </p>
    </div>
    <div style="background: #f1f5f9; padding: 20px 24px; text-align: center; font-size: 12px; color: #64748b; border-top: 1px solid #e2e8f0;">
      <p style="margin: 0;">&copy; 2026 ACYA. Tous droits réservés.</p>
    </div>
  </div>
</body>
</html>`;

    return {
      subject: `Bienvenue sur ACYA — ${companyName}`,
      sender: 'ACYA <noreply@acya.site>',
      html: html
    };
  },
  raw: (vars, body) => {
    const subject = body.subject ? String(body.subject).trim() : '';
    const html = body.html ? String(body.html).trim() : '';
    if (!subject || !html) {
      return { error: "Raw template requires both 'subject' and 'html' fields" };
    }
    return {
      subject: subject,
      sender: 'ACYA <support@acya.site>',
      html: html
    };
  }
};

if (!TEMPLATES[template]) {
  return [{ json: { valid: false, success: false, error: "VALIDATION_ERROR", message: `Unsupported template: '${template}'` } }];
}

const renderResult = TEMPLATES[template](body.variables, body);
if (renderResult.error) {
  return [{ json: { valid: false, success: false, error: "VALIDATION_ERROR", message: renderResult.error } }];
}

return [{
  json: {
    valid: true,
    to: to,
    sender: renderResult.sender,
    replyTo: replyTo,
    subject: renderResult.subject,
    html: renderResult.html,
    template: template,
    successResponse: {
      success: true,
      accepted: true,
      template: template
    },
    errorResponse: {
      success: false,
      error: "MAILGUN_ERROR",
      message: "Failed to send email via Mailgun API"
    }
  }
}];
